dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "phenotype",
      "label": "Phenotype",
      "type": "list",
      "values": [
        {
          "label": "POAG",
          "value": "VG_POAG"
        },
        {
          "label": "Intraocular Pressure",
          "value": "VG_intraocular_pressure"
        }
      ]
    },
    {
      "parameter": "ancestry",
      "label": "Ancestry",
      "type": "list",
      "values": [
        {
          "label": "Cross-ancestry",
          "value": "Mixed"
        },
        {
          "label": "European",
          "value": "eu"
        }
      ]
    },
    {
      "parameter": "region",
      "label": "Region (chr:start-end)",
      "type": "input",
      "values": "kp genes",
      "convert to region": "true",
      "expand region by": 100000,
      "search point": "https://vision.hugeampkpnbi.org"
    },
    {
      "parameter": "eQtlGene",
      "label": "Target gene (eQTL)",
      "type": "input",
      "values": "kp genes"
    },
    {
      "parameter": "sQtlGene",
      "label": "Target gene (sQTL)",
      "type": "input",
      "values": "kp genes"
    }
  ],
  "visualizer collection": [
    {
      "sections": [
        "associations"
      ],
      "label": "Associated variants in region"
    },
    {
      "sections": [
        "eQTL_by_region"
      ],
      "label": "eQTL by region"
    },
    {
      "sections": [
        "eQTL_by_target_gene"
      ],
      "label": "eQTL by target gene: (eQTL)"
    },
    {
      "sections": [
        "sQTL_by_region"
      ],
      "label": "sQTL by region"
    },
    {
      "sections": [
        "sQTL_by_target_gene"
      ],
      "label": "sQTL by target gene (sQTL)"
    },
    {
      "sections": [
        "sn_atacSeq_by_region_species"
      ],
      "label": "Single nucleus ATAC-seq by region & species"
    }
  ],
  "tab groups": [
    {
      "label": "Variants in region",
      "sections": [
        {
          "section": "associations",
          "label": "Associated variants in region"
        }
      ]
    },
    {
      "label": "eQTL",
      "sections": [
        {
          "section": "eQTL_by_region",
          "label": "eQTL by region"
        },
        {
          "section": "eQTL_by_target_gene",
          "label": "eQTL by target gene: (eQTL)"
        }
      ]
    },
    {
      "label": "sQTL",
      "sections": [
        {
          "section": "sQTL_by_region",
          "label": "sQTL by region"
        },
        {
          "section": "sQTL_by_target_gene",
          "label": "sQTL by target gene (sQTL)"
        }
      ]
    },
    {
      "label": "Bulk ATAC-seq",
      "sections": [
        {
          "section": "bulk_atacSeq_by_region",
          "label": "Bulk ATAC-seq by region"
        }
      ]
    },
    {
      "label": "Single nucleus ATAC-seq",
      "sections": [
        {
          "section": "sn_atacSeq_by_region_species",
          "label": "Single nucleus ATAC-seq by region & species"
        }
      ]
    }
  ],
  "sections": [
    {
      "section id": "associations",
      "header": "GWAS: Associated Variants in Region",
      "data point": {
        "type": "bioindex",
        "url": "https://vision.hugeampkpnbi.org/api/bio/",
        "index": "associations",
        "parameters": [
          "phenotype",
          "ancestry",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "initial sort by": {
          "field": "P-value",
          "direction": "desc"
        },
        "data zoom": {
          "chromosome": "Chromosome",
          "position": "Position"
        },
        "data convert": [
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Ancestry",
            "raw field": "ancestry"
          },
          {
            "type": "raw",
            "field name": "chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "position"
          },
          {
            "type": "raw",
            "field name": "ref",
            "raw field": "reference"
          },
          {
            "type": "raw",
            "field name": "alt",
            "raw field": "alt"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "unscaled_beta"
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf"
          },
          {
            "type": "raw",
            "field name": "Standard Error",
            "raw field": "stdErr"
          },
          {
            "type": "raw",
            "field name": "Consequence",
            "raw field": "consequence"
          },
          {
            "type": "raw",
            "field name": "Z-score",
            "raw field": "zScore"
          },
          {
            "type": "raw",
            "field name": "P-value",
            "raw field": "pValue"
          },
          {
            "type": "raw",
            "field name": "rsID",
            "raw field": "dbSNP"
          },
          {
            "type": "join",
            "field name": "PhenotypeAncestry",
            "fields to join": [
              "phenotype",
              "ancestry"
            ],
            "join by": "_"
          },
          {
            "type": "replace characters",
            "field name": "Phenotype/Ancestry",
            "raw field": "PhenotypeAncestry",
            "replace": [
              {
                "from": "VG_",
                "to": ""
              },
              {
                "from": "Mixed",
                "to": "CrossAnc"
              },
              {
                "from": "EU",
                "to": "EUR"
              },
              {
                "from": "Intraocular_pressure",
                "to": "IOP"
              }
            ]
          },
          {
            "type": "join",
            "field name": "REF/ALT",
            "fields to join": [
              "reference",
              "alt"
            ],
            "join by": "/"
          },
          {
            "type": "join",
            "field name": "Locus",
            "fields to join": [
              "chromosome",
              "position"
            ],
            "join by": ":"
          },
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              "_",
              "_",
              "_"
            ]
          },
          {
            "type": "join multi",
            "field name": "LD Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "raw",
            "field name": "chr",
            "raw field": "chromosome"
          },
          {
            "type": "raw",
            "field name": "RS ID",
            "raw field": "varId"
          },
          {
            "type": "calculate",
            "field name": "P-value(-log10)",
            "raw field": "pValue",
            "calculation type": "-log10"
          }
        ],
        "top rows": [
          "Phenotype/Ancestry",
          "Variant ID",
          "RS ID",
          "REF/ALT",
          "P-value",
          "Beta",
          "Standard Error",
          "Z-score"
        ],
        "star column": "Variant ID",
        "tool tips": {
          "Variant ID": "chromosome:position (hg38)_ref/alt",
          "RS ID": "Variant ID from dbGaP",
          "REF/ALT": "Reference allele/alternate allele",
          "P-value": "Significance of association with the selected phenotype(s)",
          "Beta": "Effect size",
          "MAF": "Minor allele frequency",
          "Z-score": "Beta / Standard error",
          "Consequence": "Impact of the variant for overlapping genes or transcripts, as predicted by the Ensembl Variant Effect Predictor (VEP)",
          "Credible Set": "Posterior Probability of Association for the variant in the selected credible set(s)"
        },
        "locus field": "Locus",
        "column formatting": {
          "P-value": {
            "type": [
              "scientific notation"
            ]
          },
          "Odds Ratio": {
            "type": [
              "scientific notation"
            ]
          },
          "Beta": {
            "type": [
              "scientific notation",
              "fixed 5"
            ]
          },
          "EAF": {
            "type": [
              "scientific notation"
            ]
          },
          "MAF": {
            "type": [
              "scientific notation"
            ]
          },
          "Standard Error": {
            "type": [
              "scientific notation"
            ]
          },
          "Z-score": {
            "type": [
              "scientific notation",
              "fixed 3"
            ]
          },
          "Target Gene": {
            "type": [
              "link"
            ],
            "link to": "/gene.html?gene=",
            "new tab": "true"
          }
        }
      },
      "filters": [
        {
          "field": "Variant ID",
          "label": "Variant ID",
          "type": "search",
          "features": [
            "autocomplete"
          ],
          "label in bubble": "true"
        },
        {
          "field": "rsID",
          "label": "rsID",
          "type": "search",
          "features": [
            "autocomplete"
          ],
          "label in bubble": "true"
        },
        {
          "field": "P-value",
          "label": "P-value (<=)",
          "type": "search lower than",
          "label in bubble": "true"
        },
        {
          "field": "LDS",
          "label": "LD score (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "EAF",
          "label": "EAF (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Beta",
          "label": "Beta (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Z-score",
          "label": "Z-score (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        }
      ],
      "visualizer": {
        "propagateLD": "send",
        "star key": "Variant ID",
        "zoom": "true",
        "type": "region plot",
        "genome reference": "GRCh38",
        "x axis field": "Position",
        "y axis field": "P-value(-log10)",
        "render by": "LD Variant ID",
        "y axis label": "P-value(-log10)",
        "x axis label": "Chromosome",
        "hover content": [
          "P-value",
          "Beta"
        ],
        "height": 120,
        "ld server": {
          "pos": "Position",
          "ref": "ref",
          "alt": "alt",
          "ref variant field": "LD Variant ID",
          "populations field": "P-value",
          "populations type": "fixed",
          "fixed population": "ALL",
          "populations": {
            "ALL": "ALL"
          }
        },
        "genes track": {
          "input type": "dynamic",
          "dynamic parameter": "region",
          "search point": "https://vision.hugeampkpnbi.org",
          "show all biotypes": true
        },
        "input type": "dynamic",
        "dynamic parameter": "region",
        "if combine y axis field": {
          "type": "average",
          "field": "P-value(-log10)"
        },
        "plot margin": {
          "left": 200,
          "right": 200,
          "top": 30,
          "bottom": 100,
          "bump": 10
        }
      }
    },
    {
      "section id": "eQTL_by_region",
      "header": "eQTL by region",
      "data point": {
        "type": "bioindex",
        "url": "https://vision.hugeampkpnbi.org/api/bio/",
        "index": "variant-links",
        "parameters": [
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "tss_distance",
            "raw field": "tss_distance"
          },
          {
            "type": "raw",
            "field name": "Colocalized",
            "raw field": "Colocalized",
            "if no value": "0"
          },
          {
            "type": "raw",
            "field name": "QTL type",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "Target gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Variant ID",
            "raw field": "variant"
          },
          {
            "type": "raw",
            "field name": "RS ID",
            "raw field": "rsid"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "QTL_beta"
          },
          {
            "type": "raw",
            "field name": "P-value",
            "raw field": "QTL_p"
          },
          {
            "type": "calculate",
            "field name": "P-value(-log10)",
            "raw field": "QTL_p",
            "calculation type": "-log10"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "source"
          },
          {
            "type": "raw",
            "field name": "Gencode ID",
            "raw field": "gene_id"
          },
          {
            "type": "replace characters",
            "field name": "Dataset",
            "raw field": "dataset",
            "replace": [
              {
                "from": "_VG",
                "to": ""
              }
            ]
          },
          {
            "type": "join multi",
            "field name": "Trait/GWAS raw",
            "fields to join": [
              "phenotype",
              "ancestry"
            ],
            "join by": [
              "_"
            ]
          },
          {
            "type": "replace characters",
            "field name": "Trait/GWAS",
            "raw field": "Trait/GWAS raw",
            "replace": [
              {
                "from": "VG_",
                "to": ""
              }
            ]
          },
          {
            "type": "raw",
            "field name": "GWAS variant (hg38)",
            "raw field": "gwas_variant"
          },
          {
            "type": "raw",
            "field name": "QTL variant",
            "raw field": "variant"
          },
          {
            "type": "raw",
            "field name": "QTL effect allele (ALT)",
            "raw field": "QTL_effect_allele"
          },
          {
            "type": "raw",
            "field name": "GWAS p-value of QTL variant",
            "raw field": "QTL_pValue_GWAS"
          },
          {
            "type": "raw",
            "field name": "GWAS beta relative to QTL ALT",
            "raw field": "QTL_beta_GWAS"
          },
          {
            "type": "raw",
            "field name": "QTL/GWAS relative direction of effect",
            "raw field": "QTL_GWAS_effect_dir"
          },
          {
            "type": "raw",
            "field name": "CLPP (eCAVIAR)",
            "raw field": "CLPP",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "RCP (enloc)",
            "raw field": "RCP",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Pass QC",
            "raw field": "Pass_QC"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "start"
          },
          {
            "type": "raw",
            "field name": "Start",
            "raw field": "start"
          },
          {
            "type": "calculate",
            "field name": "End",
            "expression": [
              "end",
              "+",
              2
            ],
            "calculation type": "math"
          },
          {
            "type": "join multi",
            "field name": "Region",
            "fields to join": [
              "Start",
              "End"
            ],
            "join by": [
              "-"
            ]
          },
          {
            "type": "join multi",
            "field name": "RS ID / Tissue / Target gene",
            "fields to join": [
              "RS ID",
              "Tissue",
              "Target gene"
            ],
            "join by": [
              "_",
              "_"
            ]
          }
        ],
        "top rows": [
          "QTL type",
          "Target gene",
          "Gencode ID",
          "Tissue",
          "Variant ID",
          "RS ID",
          "P-value",
          "Beta",
          "Source",
          "Dataset"
        ],
        "column formatting": {
          "Beta": {
            "type": [
              "scientific notation",
              "fixed 5"
            ]
          }
        },
        "features": [
          "Evidence"
        ],
        "features header": "Colocalization",
        "features required column": [
          "features",
          "Evidence",
          0,
          "GWAS variant (hg38)"
        ],
        "Evidence": [
          "Trait/GWAS",
          "GWAS variant (hg38)",
          "QTL variant",
          "QTL effect allele (ALT)",
          "GWAS p-value of QTL variant",
          "GWAS beta relative to QTL ALT",
          "QTL/GWAS relative direction of effect",
          "CLPP (eCAVIAR)",
          "RCP (enloc)",
          "Pass QC"
        ]
      },
      "visualizers": {
        "wrapper type": "grouped tabs",
        "groups": [
          {
            "label": "Grouped by RS ID / Tissue / Target gene",
            "visualizers": [
              {
                "label": "Variants: grouped by tissue, colored by target gene",
                "type": "region track",
                "zoom": "true",
                "render by": "Region",
                "x axis field": "Position",
                "y axis field": "Tissue",
                "hover content": [
                  "QTL type",
                  "Target gene",
                  "Gencode ID",
                  "Tissue",
                  "Variant ID",
                  "RS ID",
                  "P-value",
                  "Beta",
                  "Source",
                  "Dataset",
                  "tss_distance"
                ],
                "color by": "Target gene",
                "track height": 12,
                "plot margin": {
                  "left": 200,
                  "right": 200,
                  "top": 30,
                  "bottom": 100,
                  "bump": 10
                },
                "genome reference": "GRCh38"
              },
              {
                "label": "Rendered by variants",
                "star key": "Variant ID",
                "zoom": "true",
                "propagateLD": "receive",
                "type": "region plot",
                "genome reference": "GRCh38",
                "x axis field": "Position",
                "y axis field": "P-value(-log10)",
                "render by": "RS ID / Tissue / Target gene",
                "y axis label": "P-value(-log10)",
                "x axis label": "Chromosome",
                "hover content": [
                  "P-value",
                  "Beta"
                ],
                "height": 120,
                "genes track": {
                  "input type": "dynamic",
                  "dynamic parameter": "region",
                  "search point": "https://vision.hugeampkpnbi.org",
                  "show all biotypes": true
                },
                "input type": "dynamic",
                "dynamic parameter": "region",
                "if combine y axis field": {
                  "type": "average",
                  "field": "P-value(-log10)"
                },
                "plot margin": {
                  "left": 200,
                  "right": 200,
                  "top": 30,
                  "bottom": 100,
                  "bump": 10
                }
              }
            ]
          },
          {
            "label": "Grouped by target gene, colored by tissue",
            "visualizers": [
              {
                "label": "Variants: grouped by target gene, colored by tissue",
                "type": "region track",
                "zoom": "true",
                "render by": "Region",
                "x axis field": "Position",
                "y axis field": "Target gene",
                "hover content": [
                  "QTL type",
                  "Target gene",
                  "Gencode ID",
                  "Tissue",
                  "Variant ID",
                  "RS ID",
                  "P-value",
                  "Beta",
                  "Source",
                  "Dataset",
                  "tss_distance"
                ],
                "color by": "Tissue",
                "track height": 12,
                "plot margin": {
                  "left": 200,
                  "right": 200,
                  "top": 30,
                  "bottom": 100,
                  "bump": 10
                },
                "genome reference": "GRCh38"
              },
              {
                "label": "Rendered by RS ID / Tissue / Target gene",
                "star key": "Variant ID",
                "zoom": "true",
                "propagateLD": "receive",
                "type": "region plot",
                "genome reference": "GRCh38",
                "x axis field": "Position",
                "y axis field": "P-value(-log10)",
                "render by": "RS ID / Tissue / Target gene",
                "y axis label": "P-value(-log10)",
                "x axis label": "Chromosome",
                "hover content": [
                  "P-value",
                  "Beta"
                ],
                "height": 120,
                "genes track": {
                  "input type": "dynamic",
                  "dynamic parameter": "region",
                  "search point": "https://vision.hugeampkpnbi.org",
                  "show all biotypes": true
                },
                "input type": "dynamic",
                "dynamic parameter": "region",
                "if combine y axis field": {
                  "type": "average",
                  "field": "P-value(-log10)"
                },
                "plot margin": {
                  "left": 200,
                  "right": 200,
                  "top": 30,
                  "bottom": 100,
                  "bump": 10
                }
              }
            ]
          }
        ]
      },
      "filters": [
        {
          "field": "Target gene",
          "label": "Target gene",
          "type": "checkbox"
        },
        {
          "field": "Variant ID",
          "label": "Variant ID",
          "type": "search",
          "features": [
            "autocomplete"
          ],
          "label in bubble": "true"
        },
        {
          "field": "RS ID",
          "label": "RS ID",
          "type": "search",
          "features": [
            "autocomplete"
          ],
          "label in bubble": "true"
        },
        {
          "field": "Source",
          "label": "Source",
          "type": "checkbox"
        },
        {
          "field": "Tissue",
          "label": "Tissue",
          "type": "checkbox"
        },
        {
          "field": "Colocalized",
          "label": "Colocalized",
          "type": "checkbox"
        }
      ]
    },
    {
      "section id": "eQTL_by_target_gene",
      "header": "eQTL by target gene ($eQtlGene)",
      "data point": {
        "type": "bioindex",
        "url": "https://vision.hugeampkpnbi.org/api/bio/",
        "index": "variant-links-gene",
        "parameters": [
          "eQtlGene"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "tss_distance",
            "raw field": "tss_distance"
          },
          {
            "type": "raw",
            "field name": "Colocalized",
            "raw field": "Colocalized",
            "if no value": "0"
          },
          {
            "type": "raw",
            "field name": "QTL type",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "Target gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Variant ID",
            "raw field": "variant"
          },
          {
            "type": "raw",
            "field name": "RS ID",
            "raw field": "rsid"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "QTL_beta"
          },
          {
